std::vector<torch::Tensor> prefix512(torch::Tensor input) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == 512 && input.size(2) == 512,
              "prefix512 requires shape [batch, 512, 512]");
  const c10::cuda::CUDAGuard device_guard(input.device());
  constexpr int n = 512;
  constexpr int kPrefixColumns = 8;
  constexpr int kReducerBlocks = 2;
  const int batch = static_cast<int>(input.size(0));
  const int packed_size = n * (n + 1) / 2;
  auto packed = torch::empty({batch, packed_size}, input.options());
  auto transformed = torch::empty_like(input);
  auto prefix_reflectors =
      torch::zeros({batch, n - 1, kPrefixColumns}, input.options());
  auto diagonal = torch::empty({batch, n}, input.options());
  auto off_diagonal = torch::zeros({batch, n}, input.options());
  auto taus = torch::zeros({batch, n}, input.options());

  cudaLaunchConfig_t config = {};
  config.gridDim = dim3(batch * kReducerBlocks, 1, 1);
  config.blockDim = dim3(768, 1, 1);
  config.dynamicSmemBytes = (3 * n + 40) * sizeof(float);
  cudaLaunchAttribute attribute = {};
  attribute.id = cudaLaunchAttributeClusterDimension;
  attribute.val.clusterDim.x = kReducerBlocks;
  attribute.val.clusterDim.y = 1;
  attribute.val.clusterDim.z = 1;
  config.attrs = &attribute;
  config.numAttrs = 1;
  const cudaError_t launch_status = cudaLaunchKernelEx(
      &config, reduce_packed_prefix_clustered<kReducerBlocks, n, kPrefixColumns>,
      input.data_ptr<float>(), packed.data_ptr<float>(),
      diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
      taus.data_ptr<float>(), transformed.data_ptr<float>(),
      prefix_reflectors.data_ptr<float>());
  TORCH_CHECK(launch_status == cudaSuccess,
              "clustered n512 prefix launch failed: ",
              cudaGetErrorString(launch_status));
  return {transformed, prefix_reflectors, diagonal, off_diagonal, taus};
}

