  auto vectors = torch::empty({batch, n, n}, diagonal.options());
  auto values = torch::empty({batch, n}, diagonal.options());
  auto info = torch::zeros({batch}, diagonal.options().dtype(torch::kInt32));
  tridiagonal_eigh_global<kEigenpairsPerBlock, n, 25><<<
      batch * kTilesPerMatrix, kEigenpairsPerBlock, 3 * n * sizeof(float)>>>(
      diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
      values.data_ptr<float>(), vectors.data_ptr<float>(),
      factor_workspace.data_ptr<float>(), info.data_ptr<int>());
  return {vectors, values};
}

std::vector<torch::Tensor> sytrd_panel512(
    torch::Tensor matrix, torch::Tensor reflectors,
    torch::Tensor diagonal, torch::Tensor off_diagonal, torch::Tensor taus,
    int64_t start, int64_t width) {
  TORCH_CHECK(matrix.is_cuda() && matrix.scalar_type() == torch::kFloat32,
              "matrix must be an FP32 CUDA tensor");
  TORCH_CHECK(matrix.dim() == 3 && matrix.size(1) == 512 &&
                  matrix.size(2) == 512 && matrix.is_contiguous(),
              "sytrd_panel512 requires contiguous [batch, 512, 512]");
  TORCH_CHECK(width > 0 && width <= 16 && start >= 8 &&
                  start + width <= 510,
              "invalid n512 panel interval");
  const c10::cuda::CUDAGuard device_guard(matrix.device());
  constexpr int n = 512;
  constexpr int kPanelWidth = 16;
  const int batch = static_cast<int>(matrix.size(0));
  const int update_rows = n - static_cast<int>(start + width);
  auto panel_v = torch::empty({batch, update_rows, width}, matrix.options());
  auto panel_w = torch::empty({batch, update_rows, width}, matrix.options());
  const int shared_bytes =
      (2 * n * kPanelWidth + 32 + 2 * kPanelWidth) * sizeof(float);
  if (start < 264) {
    cudaFuncSetAttribute(sytrd_panel_kernel<n, kPanelWidth, true>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         shared_bytes);
    sytrd_panel_kernel<n, kPanelWidth, true><<<batch, 512, shared_bytes>>>(
        matrix.data_ptr<float>(), panel_v.data_ptr<float>(),
        panel_w.data_ptr<float>(), reflectors.data_ptr<float>(),
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        taus.data_ptr<float>(), static_cast<int>(start),
        static_cast<int>(width));
  } else {
    cudaFuncSetAttribute(sytrd_panel_kernel<n, kPanelWidth, false>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         shared_bytes);
    sytrd_panel_kernel<n, kPanelWidth, false><<<batch, 512, shared_bytes>>>(
        matrix.data_ptr<float>(), panel_v.data_ptr<float>(),
        panel_w.data_ptr<float>(), reflectors.data_ptr<float>(),
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        taus.data_ptr<float>(), static_cast<int>(start),
        static_cast<int>(width));
  }
  return {panel_v, panel_w};
}

std::vector<torch::Tensor> xsyev_batched(torch::Tensor input) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
              "input must have shape [batch, n, n]");

  const c10::cuda::CUDAGuard device_guard(input.device());
  const int64_t batch = input.size(0);
  const int64_t n = input.size(1);
  const cublasFillMode_t uplo =
      n >= 2048 ? CUBLAS_FILL_MODE_UPPER : CUBLAS_FILL_MODE_LOWER;
  auto vectors_col_major = input.contiguous().clone();
  auto values = torch::empty({batch, n}, input.options());

  SolverState& s = state();

  if (s.n != n || s.batch != batch) {
#if defined(CUDART_VERSION) && CUDART_VERSION >= 13030 && \
    !defined(EIGH_DISABLE_BF16X9)
    const cusolverMathMode_t math_mode =
        n >= 512 ? CUSOLVER_FP32_EMULATED_BF16X9_MATH
                  : CUSOLVER_DEFAULT_MATH;
    CUSOLVER_CHECK(cusolverDnSetMathMode(s.handle, math_mode));
#endif
    size_t device_bytes = 0;
    size_t host_bytes = 0;
    CUSOLVER_CHECK(cusolverDnXsyevBatched_bufferSize(
        s.handle, s.params, CUSOLVER_EIG_MODE_VECTOR, uplo, n, CUDA_R_32F,
        vectors_col_major.data_ptr<float>(), n, CUDA_R_32F,
        values.data_ptr<float>(), CUDA_R_32F, &device_bytes, &host_bytes,
        batch));

    s.n = n;
    s.batch = batch;
    s.device_bytes = device_bytes;
    s.host_bytes = host_bytes;
    s.device_workspace = torch::empty(
        {static_cast<int64_t>(device_bytes)},
        input.options().dtype(torch::kUInt8));
    s.info = torch::empty(
        {batch}, input.options().dtype(torch::kInt32));
    s.host_workspace.resize(host_bytes);
  }

  CUSOLVER_CHECK(cusolverDnXsyevBatched(
      s.handle, s.params, CUSOLVER_EIG_MODE_VECTOR, uplo, n, CUDA_R_32F,
      vectors_col_major.data_ptr<float>(), n, CUDA_R_32F,
      values.data_ptr<float>(), CUDA_R_32F,
      s.device_bytes == 0 ? nullptr : s.device_workspace.data_ptr(),
      s.device_bytes,
      s.host_bytes == 0 ? nullptr : s.host_workspace.data(), s.host_bytes,
      s.info.data_ptr<int>(), batch));

  // cuSOLVER writes column-major eigenvectors into row-major storage.
  return {vectors_col_major.transpose(1, 2), values};
}

std::vector<torch::Tensor> eigh1024_dispatch(torch::Tensor input) {
  TORCH_CHECK(input.is_cuda() && input.scalar_type() == torch::kFloat32,
              "n1024 dispatch requires CUDA FP32 input");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == 1024 &&
                  input.size(2) == 1024 && input.is_contiguous(),
              "n1024 dispatch requires contiguous n=1024 input");
  const c10::cuda::CUDAGuard device_guard(input.device());
  const int64_t batch = input.size(0);
  dense_batch_n1024(input);
  DenseBatchState& dense_state = dense_batch_state();
  const cudaError_t sync_status = cudaDeviceSynchronize();
  TORCH_CHECK(sync_status == cudaSuccess,
              "n1024 classifier synchronization failed: ",
              cudaGetErrorString(sync_status));
  if (*dense_state.host_flag == 0) {
    return xsyev_batched(input);
  }

  auto reduced = band_eigh(input);
  auto vectors = reduced[0];
  auto values = reduced[1];
  auto reflectors = reduced[2];
  auto taus = reduced[3];
  constexpr int n = 1024;
  constexpr int block = 128;
  for (int start = 896; start >= 0; start -= block) {
    const int width = std::min(block, n - 2 - start);
    const int tail = start + 1;
    auto panel = reflectors.slice(1, tail, n).slice(
        2, start, start + width);
    auto v = panel.tril(-1);
    v.diagonal(0, 1, 2).fill_(1.0);
    auto gram = at::bmm(v.transpose(1, 2), v);
    auto panel_taus = taus.slice(1, start, start + width).contiguous();
    auto t = compact_wy_t(gram, panel_taus);
    auto panel_vectors = vectors.slice(1, tail, n);
    auto projected = at::bmm(v.transpose(1, 2), panel_vectors);
    projected = at::bmm(t, projected);
    panel_vectors.sub_(at::bmm(v, projected));
  }

  auto gram = at::bmm(vectors.transpose(1, 2), vectors);
  gram.mul_(-0.5);
  gram.diagonal(0, 1, 2).add_(1.5);
  vectors = at::bmm(vectors, gram);
  auto flags = certify_eigh(input, vectors, values);
  auto unsafe_indices = at::nonzero(
      flags.narrow(0, 0, batch)).flatten();
  if (unsafe_indices.numel() == 0) {
    return {vectors, values};
  }

  auto candidate_data = at::index_select(
      input, 0, unsafe_indices).contiguous();
  auto candidate_vectors = at::index_select(
      vectors, 0, unsafe_indices).contiguous();
  auto candidate_values = at::index_select(
      values, 0, unsafe_indices).contiguous();
  gram = at::bmm(candidate_vectors.transpose(1, 2), candidate_vectors);
  gram.mul_(-0.5);
  gram.diagonal(0, 1, 2).add_(1.5);
  candidate_vectors = at::bmm(candidate_vectors, gram);
  auto refined_flags = certify_eigh(
      candidate_data, candidate_vectors, candidate_values);
  vectors.index_copy_(0, unsafe_indices, candidate_vectors);

  auto remaining_positions = at::nonzero(
      refined_flags.narrow(0, 0, unsafe_indices.numel())).flatten();
  if (remaining_positions.numel() == 0) {
    return {vectors, values};
  }
  auto remaining_indices = at::index_select(
      unsafe_indices, 0, remaining_positions);
  if (remaining_indices.numel() * 4 >= batch * 3) {
    return xsyev_batched(input);
  }
  auto repaired = xsyev_batched(at::index_select(
      input, 0, remaining_indices).contiguous());
  vectors.index_copy_(0, remaining_indices, repaired[0]);
  values.index_copy_(0, remaining_indices, repaired[1]);
  return {vectors, values};
}

std::vector<torch::Tensor> syevj_batched(
    torch::Tensor input, double tolerance, int64_t max_sweeps) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
              "input must have shape [batch, n, n]");

  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  const int n = static_cast<int>(input.size(1));
  auto vectors_col_major = input.contiguous().clone();
  auto values = torch::empty({batch, n}, input.options());

  JacobiState& s = jacobi_state();
  if (s.tolerance != tolerance || s.max_sweeps != max_sweeps) {
    CUSOLVER_CHECK(cusolverDnXsyevjSetTolerance(s.params, tolerance));
    CUSOLVER_CHECK(cusolverDnXsyevjSetMaxSweeps(
        s.params, static_cast<int>(max_sweeps)));
    s.tolerance = tolerance;
    s.max_sweeps = static_cast<int>(max_sweeps);
  }
  if (s.n != n || s.batch != batch) {
    int lwork = 0;
    CUSOLVER_CHECK(cusolverDnSsyevjBatched_bufferSize(
        s.handle, CUSOLVER_EIG_MODE_VECTOR, CUBLAS_FILL_MODE_LOWER, n,
        vectors_col_major.data_ptr<float>(), n, values.data_ptr<float>(),
        &lwork, s.params, batch));
    s.n = n;
    s.batch = batch;
    s.lwork = lwork;
    s.workspace = torch::empty({lwork}, input.options());
    s.info = torch::empty(
        {batch}, input.options().dtype(torch::kInt32));
  }

  CUSOLVER_CHECK(cusolverDnSsyevjBatched(
      s.handle, CUSOLVER_EIG_MODE_VECTOR, CUBLAS_FILL_MODE_LOWER, n,
      vectors_col_major.data_ptr<float>(), n, values.data_ptr<float>(),
      s.workspace.data_ptr<float>(), s.lwork, s.info.data_ptr<int>(), s.params,
      batch));
  sort_eigenpairs32<<<batch, 128>>>(
      vectors_col_major.data_ptr<float>(), values.data_ptr<float>());
  return {vectors_col_major.transpose(1, 2), values};
}
